"""
Pressearchiv – forensische Sicherung von Leserkommentaren
=========================================================
Sichert je Beitrag in <Beitrag>/kommentare/:
  kommentare.json          strukturierte Kommentare (ID, Nutzername, Zeitstempel, Text, Bewertungen, Antwort auf)
  kommentare.csv           dieselben Daten für Excel
  rohdaten_*.json/html     unveränderte Server-Antworten (Primärbeweis)
  kommentare_screenshot.png Bildschirmfoto der Kommentaransicht
  sicherungsprotokoll.txt  Ablauf, Zeitpunkt (UTC + lokal), Werkzeuge, SHA-256 aller Dateien

Aufruf:  python kommentare_sichern.py quellen_wksta_salzburg-ag.json
"""
import csv
import hashlib
import json
import platform
import re
import sys
from datetime import datetime, timezone
from pathlib import Path

from bs4 import BeautifulSoup
from playwright.sync_api import sync_playwright, __version__ as pw_version

BASIS = Path(__file__).resolve().parent.parent
UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
      "(KHTML, like Gecko) Chrome/140.0 Safari/537.36")


def jetzt():
    return datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds")


def sha256(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


# ---------------------------------------------------------------- Salzburg24 (Engagently)
def s24(page, e, ziel, log):
    roh = []

    def fang(resp):
        if "engagently.com/graphql" in resp.url and "Commentar" in resp.url:
            try:
                roh.append({"url": resp.url, "status": resp.status, "zeit": jetzt(), "body": resp.json()})
            except Exception:
                pass
    page.on("response", fang)
    page.goto(e["url"], wait_until="networkidle", timeout=60000)
    log.append(f"{jetzt()}  Seite geladen: {e['url']}")
    # Kommentar-Widget laden (wird ohne Tracking-Zustimmung nicht automatisch gestartet)
    page.evaluate("""() => {
        window.tp = window.tp || {}; if (!tp.pianoId) tp.pianoId = {getToken: () => null};
        document.querySelectorAll('[data-engagently]').forEach(s => s.remove());
        const s = document.createElement('script'); s.src = 'https://frs3tf.engagently.com/engagently.js';
        s.type = 'module'; s.setAttribute('data-engagently', 'initEngagently()'); document.head.appendChild(s);
    }""")
    page.wait_for_timeout(4000)
    page.evaluate("toggleDiscussionSidebar()")
    page.wait_for_timeout(6000)
    # Antworten und ältere Kommentare aufklappen
    for _ in range(10):
        n = page.evaluate("""() => { const r = document.querySelector('egy-discussion')?.shadowRoot; if (!r) return 0;
            let n = 0; const alle = [];
            const lauf = (w) => { w.querySelectorAll('*').forEach(x => { alle.push(x); if (x.shadowRoot) lauf(x.shadowRoot); }); };
            lauf(r);
            alle.filter(b => b.tagName === 'BUTTON' && /Antwort(en)?$|Ältere Kommentare|weitere/i.test(b.textContent.trim())
                         && !/^Antworten$/.test(b.textContent.trim()) && !b.dataset.geklickt)
                .forEach(b => { b.dataset.geklickt = 1; b.click(); n++; });
            return n; }""")
        page.wait_for_timeout(2500)
        if not n:
            break
    sidebar = page.locator("#engagently-page-drawer")
    sidebar.screenshot(path=str(ziel / "kommentare_screenshot.png"))
    sichtbar = page.evaluate("""() => { const r = document.querySelector('egy-discussion').shadowRoot;
        return r.textContent.replace(/\\s+/g, ' '); }""")
    (ziel / "rohdaten_ansicht.txt").write_text(sichtbar, encoding="utf-8")
    daten = page.evaluate("""() => { const d = document.querySelector('egy-discussion');
        return JSON.parse(atob(d.getAttribute('discussion-data').split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))); }""")
    (ziel / "rohdaten_diskussion_metadaten.json").write_text(json.dumps(daten, ensure_ascii=False, indent=2), encoding="utf-8")
    log.append(f"{jetzt()}  Diskussions-Metadaten (JWT) gesichert; Diskussionstitel: {daten['discussion']['title']!r}")
    for i, r in enumerate(roh):
        (ziel / f"rohdaten_api_{i + 1}.json").write_text(json.dumps(r, ensure_ascii=False, indent=2), encoding="utf-8")
    log.append(f"{jetzt()}  {len(roh)} API-Antworten (GraphQL) gesichert")
    return parse_engagently(roh)


def parse_engagently(roh):
    """Sucht rekursiv alle Kommentar-Objekte in den GraphQL-Antworten."""
    gefunden = {}

    def lauf(o, eltern=None):
        if isinstance(o, dict):
            text = o.get("content") or o.get("text") or o.get("body")
            if o.get("id") and isinstance(text, str) and ("createdAt" in o or "created_at" in o):
                autor = o.get("author") or o.get("user") or {}
                reakt = o.get("reactions") or o.get("reactionCounts") or o.get("reactionSummary")
                gefunden[o["id"]] = {
                    "id": o["id"],
                    "nutzername": (autor.get("displayName") or autor.get("name") or autor.get("username")
                                   if isinstance(autor, dict) else str(autor)),
                    "nutzer_id": autor.get("id") if isinstance(autor, dict) else None,
                    "zeitstempel": o.get("createdAt") or o.get("created_at"),
