def zaehlen(page, e, ziel, log):
    page.goto(e["url"], wait_until="networkidle", timeout=60000)
    txt = page.inner_text("body")
    m = re.search(r"(\d+)\s+KOMMENTARE?", txt, re.I)
    log.append(f"{jetzt()}  Seite geladen; Kommentarzähler: {m.group(0) if m else 'keine Kommentarfunktion gefunden'}")
    page.screenshot(path=str(ziel / "kommentare_screenshot.png"), full_page=False)
    return []


PARSER = {"s24-339251": s24, "sn-674574": sn, "ooen-4215774": zaehlen,
          "enm-2026-09-25": zaehlen, "orf-sbg-3372554": zaehlen}


def main():
    quellen = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
    gesamt = []
    with sync_playwright() as p:
        browser = p.chromium.launch()
        for e in quellen:
            fn = PARSER.get(e["id"])
            if not fn:
                continue
            ziel = BASIS / e["ordner"] / "kommentare"
            ziel.mkdir(parents=True, exist_ok=True)
            ctx = browser.new_context(user_agent=UA, locale="de-AT", viewport={"width": 1280, "height": 1600})
            page = ctx.new_page()
            log = [f"SICHERUNGSPROTOKOLL LESERKOMMENTARE",
                   f"Beitrag : {e['medium']} – {e.get('titel') or e['url']}",
                   f"URL     : {e['url']}",
                   f"Beginn  : {jetzt()}  (UTC: {datetime.now(timezone.utc).isoformat(timespec='seconds')})",
                   f"System  : {platform.platform()}, Python {platform.python_version()}, Playwright {pw_version} / Chromium",
                   f"Methode : automatisierter Abruf ohne Anmeldung, ohne Zustimmung zu Tracking-Cookies; "
                   f"Rohdaten unverändert gespeichert", ""]
            try:
                kom = fn(page, e, ziel, log)
            except Exception as ex:
                log.append(f"{jetzt()}  FEHLER: {ex}")
                kom = []
            ctx.close()
            for k in kom:
                k["medium"] = e["medium"]; k["beitrag_url"] = e["url"]; k["gesichert"] = jetzt()
            (ziel / "kommentare.json").write_text(json.dumps(kom, ensure_ascii=False, indent=2), encoding="utf-8")
            with open(ziel / "kommentare.csv", "w", encoding="utf-8-sig", newline="") as f:
                w = csv.writer(f, delimiter=";")
                w.writerow(["Nr", "Kommentar-ID", "Nutzername", "Zeitstempel", "Antwort auf", "Text", "Bewertungen"])
                for i, k in enumerate(kom, 1):
                    w.writerow([i, k["id"], k.get("nutzername"), k.get("zeitstempel"), k.get("antwort_auf") or "",
                                k["text"], json.dumps(k.get("bewertungen"), ensure_ascii=False)])
            log += ["", f"Ende    : {jetzt()}", f"Anzahl Kommentare: {len(kom)}", "", "SHA-256 der gesicherten Dateien:"]
            log += [f"  {sha256(f)}  {f.name}" for f in sorted(ziel.iterdir())
                    if f.is_file() and f.name != "sicherungsprotokoll.txt"]
            (ziel / "sicherungsprotokoll.txt").write_text("\n".join(log) + "\n", encoding="utf-8")
            print(f"{e['id']}: {len(kom)} Kommentare")
            gesamt += kom
        browser.close()
    alle = BASIS / quellen[0]["ordner"].split("/")[0] / "03_Kommentare_gesamt.json"
    alle.write_text(json.dumps(gesamt, ensure_ascii=False, indent=2), encoding="utf-8")


