# ---------------------------------------------------------------- derStandard (Forum-GraphQL)
def standard(page, e, ziel, log):
    page.goto(e["url"], wait_until="networkidle", timeout=60000)
    for fr in page.frames:
        try:
            fr.get_by_role("button", name=re.compile("Einverstanden")).first.click(timeout=2500)
            log.append(f"{jetzt()}  Cookie-Zustimmung 'Einverstanden' erteilt (auf Anweisung des Auftraggebers, "
                       f"nur im isolierten Archiv-Browser)")
            break
        except Exception:
            pass
    page.wait_for_timeout(4000)
    roh = []

    def fang(r):
        if "capi.ds.at/forum" in r.url:
            try:
                roh.append({"url": r.url, "status": r.status, "zeit": jetzt(), "body": r.json()})
            except Exception:
                pass
    page.on("response", fang)
    page.goto(e["url"], wait_until="networkidle", timeout=60000)
    log.append(f"{jetzt()}  Seite geladen: {e['url']}")
    for _ in range(25):
        page.mouse.wheel(0, 2000); page.wait_for_timeout(300)
    page.wait_for_timeout(4000)
    try:
        page.locator("dst-forum, #forumcontainer, [id*=forum]").first.screenshot(
            path=str(ziel / "kommentare_screenshot.png"), timeout=20000)
    except Exception:
        page.screenshot(path=str(ziel / "kommentare_screenshot.png"), full_page=True)
    for i, r in enumerate(roh):
        (ziel / f"rohdaten_api_{i + 1}.json").write_text(json.dumps(r, ensure_ascii=False, indent=2), encoding="utf-8")
    log.append(f"{jetzt()}  {len(roh)} API-Antworten (Forum-GraphQL) gesichert")
    aus = {}

    def lauf(o, eltern=None):
        if isinstance(o, dict):
            if o.get("__typename") == "Posting":
                reakt = {a["name"]: a["value"] for a in (o.get("reactions") or {}).get("aggregated", [])}
                aus[o["id"]] = {
                    "id": o["id"],
                    "posting_id_alt": (o.get("legacy") or {}).get("postingId"),
                    "nutzername": (o.get("author") or {}).get("name") or "",
                    "nutzer_id": (o.get("author") or {}).get("id"),
                    "zeitstempel": (o.get("history") or {}).get("created"),
                    "status": o.get("lifecycleStatus"),
                    "titel": o.get("title") or "",
                    "text": o.get("text") or "",
                    "antwort_auf": eltern,
                    "thread": o.get("rootPostingId"),
                    "bewertungen": {"positiv": reakt.get("positive"), "negativ": reakt.get("negative")},
                }
                eltern = o["id"]
            for v in o.values():
                lauf(v, eltern)
        elif isinstance(o, list):
            for v in o:
                lauf(v, eltern)
    for r in roh:
        lauf(r["body"])
